import { test, expect } from '@playwright/test';

test.describe('Delete Single Notification', () => {
  test.beforeEach(async ({ page }) => {
    // Navigate to the notifications page
    await page.goto('/notifications');

    // Wait for notifications to load
    await page.waitForLoadState('networkidle');
  });

  test('should delete a notification by clicking delete button on notification item', async ({ page }) => {
    // Get the first notification in the list
    const firstNotification = page.getByRole('listitem').first();

    // Verify the notification exists
    await expect(firstNotification).toBeVisible();

    // Get the initial count of notifications
    const notificationsBefore = await page.getByRole('listitem').count();

    // Hover over the notification to reveal delete button
    await firstNotification.hover();

    // Click the delete button within the notification
    const deleteButton = firstNotification.getByRole('button', { name: /delete|remove/i });
    await expect(deleteButton).toBeVisible();
    await deleteButton.click();

    // Handle confirmation dialog if present
    const confirmButton = page.getByRole('button', { name: /confirm|yes|delete/i }).last();
    if (await confirmButton.isVisible({ timeout: 1000 }).catch(() => false)) {
      await confirmButton.click();
    }

    // Wait for the notification to be removed from DOM
    await page.waitForLoadState('networkidle');

    // Verify the notification count has decreased
    const notificationsAfter = await page.getByRole('listitem').count();
    expect(notificationsAfter).toBe(notificationsBefore - 1);
  });

  test('should delete notification using context menu', async ({ page }) => {
    // Get a notification item
    const notification = page.getByRole('listitem').first();

    // Verify notification exists
    await expect(notification).toBeVisible();

    // Get initial count
    const countBefore = await page.getByRole('listitem').count();

    // Right-click to open context menu
    await notification.click({ button: 'right' });

    // Click delete option from context menu
    const deleteOption = page.getByRole('menuitem', { name: /delete|remove/i });
    await expect(deleteOption).toBeVisible();
    await deleteOption.click();

    // Handle confirmation if present
    const confirmButton = page.getByRole('button', { name: /confirm|yes|delete/i }).last();
    if (await confirmButton.isVisible({ timeout: 1000 }).catch(() => false)) {
      await confirmButton.click();
    }

    // Wait for deletion to complete
    await page.waitForLoadState('networkidle');

    // Verify count decreased
    const countAfter = await page.getByRole('listitem').count();
    expect(countAfter).toBe(countBefore - 1);
  });

  test('should show success message after deleting notification', async ({ page }) => {
    // Get first notification
    const notification = page.getByRole('listitem').first();
    await expect(notification).toBeVisible();

    // Hover and delete
    await notification.hover();
    const deleteButton = notification.getByRole('button', { name: /delete|remove/i });
    await deleteButton.click();

    // Handle confirmation
    const confirmButton = page.getByRole('button', { name: /confirm|yes|delete/i }).last();
    if (await confirmButton.isVisible({ timeout: 1000 }).catch(() => false)) {
      await confirmButton.click();
    }

    // Check for success message
    const successMessage = page.getByRole('status').or(page.getByText(/deleted|removed|success/i));
    await expect(successMessage).toBeVisible({ timeout: 5000 });
  });

  test('should not delete notification when canceling confirmation dialog', async ({ page }) => {
    // Get first notification
    const notification = page.getByRole('listitem').first();
    const notificationText = await notification.textContent();

    // Get count before
    const countBefore = await page.getByRole('listitem').count();

    // Hover and click delete
    await notification.hover();
    const deleteButton = notification.getByRole('button', { name: /delete|remove/i });
    await deleteButton.click();

    // Click cancel on confirmation dialog
    const cancelButton = page.getByRole('button', { name: /cancel|no/i });
    if (await cancelButton.isVisible({ timeout: 1000 }).catch(() => false)) {
      await cancelButton.click();
    }

    // Verify count hasn't changed
    const countAfter = await page.getByRole('listitem').count();
    expect(countAfter).toBe(countBefore);

    // Verify the notification still exists
    const stillExists = await page.getByText(notificationText || '').isVisible();
    expect(stillExists).toBeTruthy();
  });

  test('should handle deletion of notification with special characters in title', async ({ page }) => {
    // Find a notification with special characters (or create scenario)
    const notifications = page.getByRole('listitem');
    const countBefore = await notifications.count();

    // Get any notification and delete it
    const targetNotification = notifications.first();
    await targetNotification.hover();

    const deleteButton = targetNotification.getByRole('button', { name: /delete|remove/i });
    await deleteButton.click();

    // Confirm deletion
    const confirmButton = page.getByRole('button', { name: /confirm|yes|delete/i }).last();
    if (await confirmButton.isVisible({ timeout: 1000 }).catch(() => false)) {
      await confirmButton.click();
    }

    // Wait and verify
    await page.waitForLoadState('networkidle');
    const countAfter = await page.getByRole('listitem').count();
    expect(countAfter).toBe(countBefore - 1);
  });
});
